const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to today's short lecture on our hypothetical campus food waste observation project.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.5385},{"speaker":"A","text":"We designed this study because universities often struggle with excessive cafeteria leftovers during busy weekdays.","position":2,"audioStartSeconds":6.7385,"audioEndSeconds":14.097541666666666},{"speaker":"A","text":"If researchers watch dining halls carefully, they can measure exactly how much uneaten food goes into the bins.","position":3,"audioStartSeconds":14.297541666666667,"audioEndSeconds":21.282041666666668},{"speaker":"A","text":"During our simulated trial last month, student volunteers monitored trays at three main campus canteens.","position":4,"audioStartSeconds":21.482041666666667,"audioEndSeconds":28.531041666666667},{"speaker":"A","text":"The primary objective was finding out which meal period generates the highest quantity of organic rubbish.","position":5,"audioStartSeconds":28.731041666666666,"audioEndSeconds":35.27741666666667},{"speaker":"A","text":"Observers recorded data on specially formatted clipboards while standing near the return belt.","position":6,"audioStartSeconds":35.47741666666667,"audioEndSeconds":41.534125},{"speaker":"A","text":"Although this method seemed straightforward, several unexpected practical limitations quickly appeared during the process.","position":7,"audioStartSeconds":41.734125,"audioEndSeconds":49.15679166666666},{"speaker":"A","text":"First, students often felt uncomfortable when volunteers stared directly at their leftover plates.","position":8,"audioStartSeconds":49.356791666666666,"audioEndSeconds":55.813},{"speaker":"A","text":"Second, varying portion sizes made accurate visual estimation very difficult for our tired observers.","position":9,"audioStartSeconds":56.013,"audioEndSeconds":62.907333333333334},{"speaker":"A","text":"Third, wet waste weighed significantly more than dry scraps, which distorted our total recorded figures.","position":10,"audioStartSeconds":63.10733333333334,"audioEndSeconds":70.02741666666667},{"speaker":"A","text":"To solve these issues, future researchers should probably use digital scales instead of guesswork.","position":11,"audioStartSeconds":70.22741666666667,"audioEndSeconds":76.54070833333333},{"speaker":"A","text":"Furthermore, installing automated cameras above the sorting area might reduce human error completely.","position":12,"audioStartSeconds":76.74070833333333,"audioEndSeconds":83.35266666666666},{"speaker":"A","text":"We hope subsequent groups will improve these techniques before launching any permanent campus sustainability campaigns.","position":13,"audioStartSeconds":83.55266666666667,"audioEndSeconds":90.74391666666666}],"questions":[{"prompt":"Project location: ______","answer":"campus","evidenceSentence":1,"evidence":"campus","explanation":"Từ khóa 'campus' xuất hiện ngay trong câu đầu tiên chỉ địa điểm của dự án."},{"prompt":"Main equipment used by volunteers: ______","answer":"clipboards","evidenceSentence":6,"evidence":"clipboards","explanation":"Tình nguyện viên ghi chép dữ liệu trên những chiếc bảng kẹp giấy (clipboards)."},{"prompt":"First practical limitation feeling: ______","answer":"uncomfortable","evidenceSentence":8,"evidence":"uncomfortable","explanation":"Hạn chế đầu tiên là học sinh cảm thấy không thoải mái (uncomfortable)."},{"prompt":"Cause of inaccurate estimation: varying ______ sizes","answer":"portion","evidenceSentence":9,"evidence":"portion","explanation":"Kích thước khẩu phần ăn khác nhau (portion sizes) gây khó khăn cho việc ước tính."},{"prompt":"Distorting factor in total figures: ______ waste","answer":"wet","evidenceSentence":10,"evidence":"wet","explanation":"Chất thải ướt (wet waste) nặng hơn đáng kể làm sai lệch tổng số liệu."},{"prompt":"Suggested replacement for guesswork: digital ______","answer":"scales","evidenceSentence":11,"evidence":"scales","explanation":"Diễn giả đề xuất sử dụng cân điện tử (digital scales) thay vì phỏng đoán."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
